<?phpinclude ('db.php');/** @var TYPE_NAME $host *//** @var TYPE_NAME $username *//** @var TYPE_NAME $pass *//** @var TYPE_NAME $dbName */if(isset($_POST['entryCounter'])){    $response=[];    if ($con = new mysqli($host, $username, $pass, $dbName)) {        $cat=["Social Science","Natural / Biological","Food","Development","Extension"];        foreach ($cat as $val){            $category=new stdClass();            $category->name=$val;            $category->total='0';            $response[]=$category;        }        $query="SELECT researchfile.category,COUNT(*) as total FROM researchfileLEFT JOIN endorsement ON researchfile.endorsementid=endorsement.idWHERE endorsement.status='accepted' AND researchfile.event=?GROUP BY researchfile.category";        $statement=$con->prepare($query);        $statement->bind_param("s",$_POST['eventType']);        $statement->execute();         $result=$statement->get_result();        while ($value=$result->fetch_assoc()){            for($x=0;$x<sizeof($response);$x++){                if($response[$x]->name===$value['category']){                    $response[$x]->total=$value['total'];                }            }        }    }    echo json_encode($response);}if(isset($_POST['perCampReport'])){    $response=[];    if ($con = new mysqli($host, $username, $pass, $dbName)) {        $camp= ['Central Office','Roxas City Main','Dayao','Pontevedra','Pilar','Dumarao','Burias','Mambusao','Tapaz','Sigma'];        foreach ($camp as $v){            $obj= new stdClass();            $obj->name=$v;            $obj->total='0';            $response[]=$obj;        }        $query="SELECT researchfile.id, researchfile.category,researchfile.campus,COUNT(*) as total FROM researchfileLEFT JOIN endorsement ON researchfile.endorsementid=endorsement.idWHERE endorsement.status='accepted'AND researchfile.category=? AND researchfile.event=?GROUP BY researchfile.campus ";        $statement=$con->prepare($query);        $statement->bind_param("ss",$_POST['category'],$_POST['eventType']);        $statement->execute();        $result=$statement->get_result();        while ($val=$result->fetch_assoc()){            for($x=0;$x<sizeof($response);$x++){                if($response[$x]->name===$val['campus']){                    $response[$x]->total=$val['total'];                }            }        }    }    echo json_encode($response);}if(isset($_POST['printSum'])){    $response=[];    if ($con = new mysqli($host, $username, $pass, $dbName)) {        $query="SELECT researchfile.campusFROM researchfileLEFT JOIN endorsement ON researchfile.endorsementid=endorsement.idWHERE endorsement.status='accepted' GROUP BY researchfile.campusORDER BY researchfile.campus ASC";        $statement=$con->prepare($query);        $statement->execute();        $result=$statement->get_result();        while ($val=$result->fetch_assoc()){            $data= new stdClass();            $data->campus=$val['campus'];            $data->catList=[];            $catList=["Social Science"	,"Natural / Biological"	,"Food",	"Development"	,"Extension"	,"TOTAL per Campus"];            foreach ($catList as $vs){                $dt=new stdClass();                $dt->name=$vs;                $dt->total='0';                $data->catList[]=$dt;            }            $quer="SELECT researchfile.category,COUNT(*) as total FROM researchfileLEFT JOIN endorsement ON researchfile.endorsementid=endorsement.idWHERE endorsement.status='accepted' AND researchfile.campus=? AND researchfile.event=?GROUP BY researchfile.category";            $stm=$con->prepare($quer);//$statement->bind_param("s",$_POST['eventName']);            $stm->bind_param("ss",$val['campus'],$_POST['eventName']);            $stm->execute();            $res=$stm->get_result();            while ($val2=$res->fetch_assoc()){                for($x=0;$x<sizeof($data->catList);$x++){                    if($val2['category']===$data->catList[$x]->name){                        $data->catList[$x]->total=$val2['total'];                    }                }            }            $response[]=$data;        }    }    echo json_encode($response);}if(isset($_POST['entryView'])){    $response=[];    if ($con = new mysqli($host, $username, $pass, $dbName)) {        $query="SELECT researchfile.id,researchfile.file,researchfile.categoryFROM researchfileLEFT JOIN endorsement ON researchfile.endorsementid=endorsement.idWHERE  researchfile.id=? AND endorsement.status='accepted' LIMIT 1";        $statement=$con->prepare($query);        $statement->bind_param("s",$_POST['docId']);        $statement->execute();        $result=$statement->get_result();        while ($val=$result->fetch_assoc()){            $response[]= $val;        }    }    echo json_encode($response);}if(isset($_POST['printEntry'])){    $response=[];    if ($con = new mysqli($host, $username, $pass, $dbName)) {        $eventName=$_POST['eventName'];        $query="SELECT event_list.id,event_list.name FROM event_list WHERE event_list.name='$eventName'";        $statement=$con->prepare($query);        $statement->execute();        $result=$statement->get_result();        while ($row=$result->fetch_assoc()){            $data=new stdClass();            $data->event=$row['name'];            $data->category=[];            $catStatement=$con->prepare("SELECT category.name FROM category");            $catStatement->execute();            $catRes=$catStatement->get_result();            while ($catRow=$catRes->fetch_assoc()){                $cat=new stdClass();                $cat->category=$catRow['name'];                $cat->docs=[];                $resQuery=$con->prepare("SELECT researchfile.id,researchfile.campus,researchfile.titleFROM researchfileLEFT JOIN endorsement ON researchfile.endorsementid=endorsement.idWHERE researchfile.category=? AND endorsement.status='accepted' AND researchfile.event=?");                $resQuery->bind_param("ss",$catRow['name'],$eventName);                $resQuery->execute();                $researchRes=$resQuery->get_result();                while ($resRow=$researchRes->fetch_assoc()){                    $resData= new stdClass();                    $resData->id=$resRow['id'];                    $resData->campus=$resRow['campus'];                    $resData->title=$resRow['title'];                    $resData->authors=[];                    $authorStatement=$con->prepare("SELECT researchfile.author,researchfile.coauthor FROM researchfile WHERE researchfile.id=?");                    $authorStatement->bind_param("s",$resRow['id']);                    $authorStatement->execute();                    $authRes=$authorStatement->get_result();                    while ($authRow=$authRes->fetch_assoc()){                       $perAuth=  array($authRow['author']);                       $perAuth=array_merge($perAuth,json_decode($authRow['coauthor']));                       $resData->authors=$perAuth;                    }                    $cat->docs[]=$resData;                }                $data->category[]=$cat;            }            $response[]=$data;        }    }    echo json_encode($response);}